  "Window": "Ventana",
  "Listening hears the microphone as it is.": "Al escuchar, se oye el micrófono tal cual.",
  "Light": "Ligero",
  "Turns down fans, hum and hiss, and keeps some of the room so quiet words are never lost.": "Reduce ventiladores, zumbidos y siseos, y conserva algo del ambiente para que nunca se pierdan las palabras dichas en voz baja.",
  "Strong": "Fuerte",
  "Removes as much background noise as it can. Best for noisy rooms; very soft speech can drop out.": "Quita todo el ruido de fondo posible. Ideal para salas ruidosas; una voz muy suave puede perderse.",
  "No microphone is connected.": "No hay ningún micrófono conectado.",
  "The microphone is blocked for this window. Allow it in the browser or System Settings → Privacy & Security.": "El micrófono está bloqueado para esta ventana. Permítelo en el navegador o en Ajustes del Sistema → Privacidad y seguridad.",
  "Move": "Mover",
  "Noise filter": "Filtro de ruido",
  "Clean the microphone before listening": "Limpiar el micrófono antes de escuchar",
  "It runs on this computer; no sound leaves it.": "Funciona en esta computadora; ningún sonido sale de ella.",
  "Check it in your room": "Pruébalo en tu sala",
  "Play the room as it is on a Sunday (fans, music, the PA) and speak. Compare the two meters.": "Recrea la sala como un domingo (ventiladores, música, sonido) y habla. Compara los dos medidores.",
  "Stop check": "Detener prueba",
  "Start check": "Iniciar prueba",
  "Room": "Sala",
  "What the microphone hears": "Lo que oye el micrófono",
  "Room level": "Nivel de la sala",
  "After the filter": "Después del filtro",
  "What listening hears": "Lo que oye la escucha",
  "Level after the filter": "Nivel después del filtro",
  "Background noise is about {cut} dB quieter after the filter.": "El ruido de fondo baja unos {cut} dB después del filtro.",
  "Little to remove here: the room is quiet, or the noise sounds like speech (music, the PA).": "Poco que quitar aquí: la sala está en silencio o el ruido suena como voz (música, sonido).",
  "In this browser": "En este navegador",
  "Light and Strong turn on the browser's own noise suppression. The desktop app has the stronger filter and the room check.": "Ligero y Fuerte activan la supresión de ruido del propio navegador. La app de escritorio tiene el filtro más fuerte y la prueba de sala.",
  "Best results": "Mejores resultados",
  "A filter removes steady noise, not the PA. If the preacher's voice comes back through the speakers mixed with music, take a feed from the sound desk (an aux send) or put a microphone near the pulpit. That helps detection more than any filter.": "Un filtro quita el ruido constante, no el sistema de sonido. Si la voz del predicador vuelve por los altavoces mezclada con música, toma una señal de la consola de sonido (un envío auxiliar) o pon un micrófono cerca del púlpito. Eso ayuda a la detección más que cualquier filtro.",
  "Microphone": "Micrófono",
  "Test microphone": "Probar micrófono",
  "Listens for 20 seconds, long enough to catch a microphone that cuts out shortly after it starts.": "Escucha durante 20 segundos, lo suficiente para detectar un micrófono que se corta poco después de empezar.",
  "Stop ({remaining}s)": "Detener ({remaining} s)",
  "Start test": "Iniciar prueba",
  "Input level": "Nivel de entrada",
  "Speak now…": "Habla ahora…",
  "Voice commands": "Comandos de voz",
  "Control the desk hands-free. Spoken verses still go to Preview either way.": "Controla la mesa sin manos. Los versículos dichos siguen yendo a Vista previa de todos modos.",
  "Require “Studio” first": "Exigir “Studio” primero",
  "Off: just say the words (“next verse”, “give me King James”). A command counts only when it is said on its own, so sermon sentences never act. On: every command starts with “Studio”.": "Desactivado: solo di las palabras (“next verse”, “give me King James”). Un comando solo cuenta si se dice por sí solo, así que las frases del sermón nunca activan nada. Activado: cada comando empieza con “Studio”.",
  "Require Studio wake word": "Exigir la palabra de activación Studio",
  "Let voice change Program (go live, cut, clear, black, logo, timer). Off every time Church Studio starts.": "Permitir que la voz cambie el Programa (salir en vivo, corte, borrar, negro, logo, temporizador). Se desactiva cada vez que se abre Church Studio.",
  "Just say": "Solo di",
  "Plain words work. These are examples; similar phrasings work too.": "Las palabras sencillas funcionan. Son ejemplos; frases parecidas también funcionan.",
  "Custom commands": "Comandos personalizados",
  "Remove {phrase}": "Quitar {phrase}",
