  "The phone and this computer must be on the same network. Next and Previous on the phone change Preview; Go live changes what the audience sees.": "El teléfono y esta computadora deben estar en la misma red. Siguiente y Anterior en el teléfono cambian la Vista previa; Salir en vivo cambia lo que ve el público.",
