  "Stream Deck and other controllers": "Stream Deck y otros controladores",
  "Add a controller": "Agregar un controlador",
  "Bitfocus Companion (Stream Deck), MIDI bridges and scripts press buttons by opening a link. Each controller gets its own key.": "Bitfocus Companion (Stream Deck), los puentes MIDI y los scripts pulsan botones abriendo un enlace. Cada controlador recibe su propia clave.",
