  "Create key": "Crear clave",
  "Links for this controller": "Enlaces para este controlador",
  "Copy them now: the key is not shown again. In Companion use a Generic HTTP \"GET\" action for each button.": "Cópialos ahora: la clave no se vuelve a mostrar. En Companion, usa una acción Generic HTTP \"GET\" para cada botón.",
  "Stream overlay": "Superposición para transmisión",
  "Add as a Browser Source (1920×1080) in OBS or vMix: the words on Program as a lower third over your camera.": "Agrégala como fuente de navegador (1920×1080) en OBS o vMix: la letra en Programa como tercio inferior sobre tu cámara.",
