  "Captions QR code is on Preview. LIVE shows it to the congregation.": "El código QR de los subtítulos está en Vista previa. EN VIVO lo muestra a la congregación.",
  "On. What is said shows as it is heard, on the screen too.": "Activado. Lo que se dice aparece a medida que se escucha, también en la pantalla.",
  "On. What is said shows as it is heard.": "Activado. Lo que se dice aparece a medida que se escucha.",
  "On, waiting for the microphone.": "Activado, esperando el micrófono.",
  "What the speaker says, as words on the screen and on phones. It uses the listening that finds verses; nothing is recorded.": "Lo que dice el predicador, como texto en la pantalla y en los teléfonos. Usa la misma escucha que encuentra versículos; no se graba nada.",
  "So far": "Hasta ahora",
  "Show on the audience screen": "Mostrar en la pantalla del público",
  "Two lines over whatever is on the screen. Program itself does not change.": "Dos líneas sobre lo que esté en la pantalla. El Programa no cambia.",
