  "People scan a QR code and follow the captions on their own phone, in their language, on the church Wi-Fi. It shows captions only.": "Las personas escanean un código QR y siguen los subtítulos en su propio teléfono, en su idioma, con el Wi-Fi de la iglesia. Solo muestra subtítulos.",
  "Captions on phones work with the desktop app, which runs the network server.": "Los subtítulos en teléfonos funcionan con la app de escritorio, que ejecuta el servidor de red.",
