  "Make link": "Crear enlace",
  "Captions QR code": "Código QR de subtítulos",
  "Scan to follow along": "Escanea para seguir",
  "Put the code on the screen before the sermon, or print it for the seats. A new link stops the old one.": "Pon el código en la pantalla antes del sermón o imprímelo para los asientos. Un enlace nuevo desactiva el anterior.",
  "QR code on Preview": "Código QR en Vista previa",
  "Copied": "Copiado",
  "A captions link is active. Make a new one to see its QR code again (the old one then stops).": "Hay un enlace de subtítulos activo. Crea uno nuevo para volver a ver su código QR (el anterior dejará de funcionar).",
  "Translate for phones": "Traducir para teléfonos",
  "Languages": "Idiomas",
  "Each phrase is translated with your AI service as it is said; phones choose their language. Up to four.": "Cada frase se traduce con tu servicio de IA mientras se dice; los teléfonos eligen su idioma. Hasta cuatro.",
