  "Nothing is watching yet.": "Nadie está recibiendo todavía.",
  "OBS, vMix or an NDI monitor can take what the audience sees, over the network. This works in the Church Studio app for Mac.": "OBS, vMix o un monitor NDI pueden recibir lo que ve el público por la red. Funciona en la app Church Studio para Mac.",
  "Find it first": "Encuéntrala primero",
  "Stop test": "Detener prueba",
  "Send test pattern": "Enviar señal de prueba",
  "Send the words for keying": "Enviar la letra para keying",
  "Sending the scripture and lyrics on Program as “{name}”, on a transparent background.": "Enviando la Escritura y la letra en Programa como “{name}”, con fondo transparente.",
  "A second source with only the scripture or lyrics on Program, as a lower third on a transparent background. Lay it over a camera in OBS or vMix. It needs no screen recording permission.": "Una segunda fuente solo con la Escritura o la letra en Programa, como tercio inferior con fondo transparente. Ponla sobre una cámara en OBS o vMix. No necesita permiso de grabación de pantalla.",
  "NDI needs the free NDI Tools or NDI Runtime on this computer:": "NDI necesita NDI Tools o NDI Runtime, gratuitos, en esta computadora:",
  "The first time, macOS asks to allow Church Studio to record the screen; that is how it sees the audience window. NDI® is a registered trademark of Vizrt NDI AB.": "La primera vez, macOS pide permitir que Church Studio grabe la pantalla; así ve la ventana del público. NDI® es una marca registrada de Vizrt NDI AB.",
  "Second screen": "Segunda pantalla",
  "{name} screen": "Pantalla {name}",
  ", words only": ", solo la letra",
  "A lobby TV, an overflow room or a hallway screen with its own look. It follows Program; nothing you prepare reaches it until LIVE.": "Una TV en el vestíbulo, una sala anexa o una pantalla de pasillo con su propio look. Sigue al Programa; nada de lo que preparas llega ahí hasta EN VIVO.",
