  "Connect a monitor, then refresh.": "Conecta un monitor y luego actualiza.",
  "This browser cannot list monitors. Open output, drag the window to the screen, then choose Fill this screen.": "Este navegador no puede listar los monitores. Abre la salida, arrastra la ventana a la pantalla y luego elige Llenar esta pantalla.",
  "Refresh": "Actualizar",
  "The audience window shows Program only. Preview, theme edits and Next stay on this desk until LIVE, Clear or Black.": "La ventana del público solo muestra el Programa. La Vista previa, los cambios de tema y Siguiente se quedan en esta mesa hasta EN VIVO, Borrar o Negro.",
  "Arrange desk and audience": "Organizar mesa y público",
  "Browser window": "Ventana del navegador",
  "A browser cannot list monitors or move a window onto one. Open output, drag it to the external display, then choose Fill this screen.": "Un navegador no puede listar los monitores ni mover una ventana a uno. Abre la salida, arrástrala a la pantalla externa y luego elige Llenar esta pantalla.",
