  "Unlock": "Desbloquear",
  "What is live now, what is next (Preview), the time and any timer. It never sends anything to the audience.": "Lo que está en vivo, lo que sigue (Vista previa), la hora y cualquier temporizador. Nunca envía nada al público.",
  "Which screen": "Qué pantalla",
  "With three screens it opens on the one that is neither the desk nor the audience. Otherwise drag it to the platform screen.": "Con tres pantallas, se abre en la que no es ni la mesa ni la del público. Si no, arrástrala a la pantalla de la plataforma.",
