  "Notes for the section on Preview show here. They never reach Preview or Program.": "Aquí se muestran las notas de la parte en Vista previa. Nunca llegan a la Vista previa ni al Programa.",
  "New part": "Parte nueva",
  "Lobby": "Vestíbulo",
  "Make one at api.planningcenteronline.com › Personal Access Tokens, then paste the application id and secret. They stay on this computer.": "Crea uno en api.planningcenteronline.com › Personal Access Tokens y luego pega el ID de la aplicación y el secreto. Se quedan en esta computadora.",
  "Pick a folder your cloud drive keeps (Google Drive, OneDrive, Dropbox, iCloud). Church Studio saves there every 30 minutes and keeps the newest 20.": "Elige una carpeta que sincronice tu nube (Google Drive, OneDrive, Dropbox, iCloud). Church Studio guarda ahí cada 30 minutos y conserva las 20 más recientes.",
  "Last backup {date}": "Último respaldo {date}",
  "On another computer, choose the same folder and restore: songs, services, sermons, slide decks, looks and layouts come across. Display settings stay per computer.": "En otra computadora, elige la misma carpeta y restaura: se copian las canciones, cultos, sermones, presentaciones, looks y diseños. Los ajustes de pantalla son de cada computadora.",
  "Backed up.": "Respaldo hecho.",
  "NIV, NKJV, ESV and others, where the publisher allows it. Get a free key at scripture.api.bible; text is fetched when shown and needs the internet.": "NVI, NKJV, ESV y otras, cuando la editorial lo permite. Obtén una clave gratis en scripture.api.bible; el texto se descarga al mostrarlo y necesita internet.",
  "{count} more in the CSV.": "{count} más en el CSV.",
  "Connect a camera, then refresh.": "Conecta una cámara y luego actualiza.",
  "If macOS refused the mic, turn Church Studio on under Microphone and Speech Recognition.": "Si macOS rechazó el micrófono, activa Church Studio en Micrófono y Reconocimiento de voz.",
  "Until {date}": "Hasta el {date}",
