  "Which AI": "Qué IA",
  "Claude, ChatGPT and Gemini work over the internet with a key from their website. An AI on this computer works without a key or the internet.": "Claude, ChatGPT y Gemini funcionan por internet con una clave de su sitio web. Una IA en esta computadora funciona sin clave ni internet.",
