  "Add music to the Walk-in playlist first.": "Primero agrega música a la lista de entrada.",
  "Walk-in started: the countdown is on the screen and the music fades at zero.": "Entrada iniciada: la cuenta regresiva está en pantalla y la música se desvanece en cero.",
  "The countdown reached zero; the walk-in music is fading out.": "La cuenta regresiva llegó a cero; la música de entrada se está desvaneciendo.",
