  "Stop walk-in": "Detener entrada",
  "Walk-in": "Entrada",
  "A countdown on the screen while walk-in music plays; the music fades when it reaches zero.": "Una cuenta regresiva en pantalla mientras suena la música de entrada; la música se desvanece al llegar a cero.",
  "Used when the service has no start time ahead today": "Se usa cuando el culto no tiene una hora de inicio próxima hoy",
