  "Remove {label}": "Quitar {label}",
  "No sounds yet": "Aún no hay sonidos",
  "Short clips you play with one click over everything else: an offering bell, an intro sting, applause. Click a playing sound again to stop it.": "Clips cortos que reproduces con un clic sobre todo lo demás: una campana para la ofrenda, una entrada musical, aplausos. Haz clic de nuevo en un sonido que suena para detenerlo.",
  "Sound output": "Salida de sonido",
  "Where the music and the sound pad play: the computer's speakers, or the sound desk's USB interface.": "Dónde suenan la música y el pad de sonidos: los parlantes de la computadora o la interfaz USB de la consola de sonido.",
  "Computer default": "Predeterminada de la computadora",
  "This computer chooses the output in its own sound settings (on a Mac: System Settings › Sound › Output).": "Esta computadora elige la salida en sus propios ajustes de sonido (en una Mac: Ajustes del Sistema › Sonido › Salida).",
  "Even volume": "Volumen uniforme",
  "Loud tracks are turned down to match the rest, so nobody rides the fader during walk-in. {n} of {total} tracks measured.": "Las pistas fuertes se bajan para igualar al resto, así nadie tiene que mover el fader durante la entrada. {n} de {total} pistas medidas.",
  "Crossfade": "Fundido cruzado",
