  "Tracks play back to back.": "Las pistas suenan una tras otra.",
  "Crossfade seconds": "Segundos de fundido cruzado",
  "Shuffle": "Aleatorio",
  "Play playlists in a new order each time, so walk-in music is not the same every week.": "Reproduce las listas en un orden nuevo cada vez, para que la música de entrada no sea la misma cada semana.",
  "Looping music fades out when you press LIVE; backing tracks play on.": "La música en bucle se desvanece al presionar EN VIVO; las pistas de acompañamiento siguen sonando.",
  "Stop a backing track with its song": "Detener la pista de acompañamiento con su canción",
