  "Chords up a semitone": "Subir acordes un semitono",
  "macOS blocked the microphone. In System Settings → Privacy & Security → Microphone, turn on Church Studio.": "macOS bloqueó el micrófono. En Ajustes del Sistema → Privacidad y seguridad → Micrófono, activa Church Studio.",
  "macOS blocked Speech Recognition. In System Settings → Privacy & Security → Speech Recognition, turn on Church Studio.": "macOS bloqueó el Reconocimiento de voz. En Ajustes del Sistema → Privacidad y seguridad → Reconocimiento de voz, activa Church Studio.",
  "The microphone or speech recognition is blocked for this site. Allow it in the browser's site settings (or System Settings → Privacy & Security), then listen again.": "El micrófono o el reconocimiento de voz están bloqueados para este sitio. Permítelos en los ajustes del sitio del navegador (o en Ajustes del Sistema → Privacidad y seguridad) y vuelve a escuchar.",
  "No microphone is available. Connect one, then listen again.": "No hay ningún micrófono disponible. Conecta uno y vuelve a escuchar.",
  "This browser cannot turn speech into words. Use Chrome or Edge, or the Church Studio desktop app.": "Este navegador no puede convertir voz en texto. Usa Chrome o Edge, o la app de escritorio de Church Studio.",
  "The microphone is blocked for this window. Allow it in the browser's site settings (or System Settings → Privacy & Security → Microphone), then listen again.": "El micrófono está bloqueado para esta ventana. Permítelo en los ajustes del sitio del navegador (o en Ajustes del Sistema → Privacidad y seguridad → Micrófono) y vuelve a escuchar.",
  "John 3:16 is on Preview": "John 3:16 está en Vista previa",
  "Press LIVE (Space) to show it on the big screen. Then pick any verse, song or slide.": "Presiona EN VIVO (Espacio) para mostrarlo en la pantalla grande. Luego elige cualquier versículo, canción o diapositiva.",
  "Your Premium trial has ended": "Tu prueba de Premium terminó",
