  "Church Studio checks your plan online now and then. Without it, this computer goes back to Free until it can check.": "Church Studio verifica tu plan en línea de vez en cuando. Sin esa verificación, esta computadora vuelve a Gratis hasta que pueda verificarlo.",
  "Connect to the internet within {n} day": "Conéctate a internet en un plazo de {n} día",
