  "Only one screen is connected. Plug in the projector or TV; without one, the audience window opens on this screen.": "Solo hay una pantalla conectada. Conecta el proyector o la TV; sin uno, la ventana del público se abre en esta pantalla.",
  "Importing a Bible file needs the desktop app.": "Para importar un archivo de Biblia necesitas la app de escritorio.",
