  "The arrow keys and the arrows on Preview step Preview. The Live arrows under Program change the screen at once.": "Las teclas de flecha y las flechas de Vista previa avanzan en Vista previa. Las flechas en vivo bajo Programa cambian la pantalla al instante.",
