  "The Production Desk trial could not start: {reason} You can start on the Presenter Desk and try again from Settings › Plan & account.": "No se pudo iniciar la prueba de la Mesa de producción: {reason} Puedes empezar en la Mesa de presentación y volver a intentarlo desde Ajustes › Plan y cuenta.",
  "Clear everything back to the theme": "Borrar todo y volver al tema",
