  "Account": "Cuenta",
  "Bring your songs from ProPresenter and EasyWorship": "Trae tus canciones de ProPresenter y EasyWorship",
  "Import ProPresenter files or a whole EasyWorship library from Songs › Import, with parts, order and CCLI details.": "Importa archivos de ProPresenter o toda una biblioteca de EasyWorship desde Canciones › Importar, con partes, orden y datos de CCLI.",
  "Your own Bible, offline": "Tu propia Biblia, sin conexión",
  "Import a Bible file in your church's language (Zefania, OSIS or OpenSong) in Settings › Bible.": "Importa un archivo de Biblia en el idioma de tu iglesia (Zefania, OSIS u OpenSong) en Ajustes › Biblia.",
  "Chords for the band": "Acordes para la banda",
  "Songs from ChordPro files show chords on the stage screen, and the song desk can change their key.": "Las canciones de archivos ChordPro muestran acordes en la pantalla de escenario, y la mesa de canciones puede cambiarles el tono.",
  "Smoother setup": "Configuración más sencilla",
  "Setup ends with a verse ready to show, and the desk says when a trial ends or the plan needs to check in.": "La configuración termina con un versículo listo para mostrar, y la mesa avisa cuando termina una prueba o el plan necesita verificarse.",
  "Undo on Program": "Deshacer en Programa",
  "Cleared or blacked the screen by mistake? Press Undo, or Command-Z (Ctrl+Z on Windows), and it comes back.": "¿Borraste o pusiste en negro la pantalla por error? Presiona Deshacer o Comando-Z (Ctrl+Z en Windows) y vuelve.",
  "Keys for song parts": "Teclas para las partes de la canción",
  "Press 1 to 9 for a part, or Shift with V, C or B for the next verse, chorus or bridge.": "Presiona del 1 al 9 para una parte, o Mayús con V, C o B para la siguiente estrofa, coro o puente.",
  "The desk tells you what happened": "La mesa te dice qué pasó",
  "A short line at the bottom explains when something could not be done, in amber when it matters.": "Una línea corta abajo explica cuando algo no se pudo hacer, en ámbar cuando es importante.",
  "Safer by default": "Más seguro de entrada",
  "Clearing the queue takes two clicks and can be undone, unsaved song edits ask first, and Preview buttons stay on Preview.": "Vaciar la cola requiere dos clics y se puede deshacer, los cambios sin guardar en canciones preguntan primero y los botones de Vista previa se quedan en Vista previa.",
  "Walk-in with a countdown": "Música de entrada con cuenta regresiva",
  "Start walk-in from Audio: the countdown goes on the screen, the music plays, and it fades by itself when the service starts.": "Inicia la entrada desde Audio: la cuenta regresiva aparece en pantalla, suena la música y se desvanece sola cuando empieza el culto.",
  "Music that sounds right": "Música que suena bien",
  "Tracks play at an even volume and fade into each other, and playlists can shuffle.": "Las pistas suenan a un volumen parejo y se funden entre sí, y las listas pueden reproducirse en orden aleatorio.",
  "A sound pad": "Un pad de sonidos",
  "Play an offering bell or an intro sting with one click, over everything else.": "Reproduce una campana para la ofrenda o una cortinilla de intro con un clic, sobre todo lo demás.",
  "Backing tracks for songs": "Pistas de acompañamiento para canciones",
  "Give a song a backing track in the song editor, and it plays when the song goes live.": "Asigna una pista de acompañamiento a una canción en el editor, y suena cuando la canción sale en vivo.",
  "Music from your phone": "Música desde tu teléfono",
  "The phone remote can play, skip and fade the music.": "El control remoto del teléfono puede reproducir, saltar y desvanecer la música.",
  "Songs line by line": "Canciones línea por línea",
  "Choose how many lines show at once with Lines on the song desk. The arrows step through them, and listening follows the line being sung.": "Elige cuántas líneas se muestran a la vez con Líneas en la mesa de canciones. Las flechas avanzan por ellas y la escucha sigue la línea que se canta.",
  "Faster verse and song detection": "Detección más rápida de versículos y canciones",
  "What is read or sung reaches Preview much sooner, even with a large song library.": "Lo que se lee o se canta llega a Vista previa mucho antes, incluso con una biblioteca grande de canciones.",
  "Your playlists stay as you left them": "Tus listas se quedan como las dejaste",
  "Church Studio now opens only once, so a second copy can no longer save over your music.": "Church Studio ahora se abre una sola vez, así que una segunda copia ya no puede sobrescribir tu música.",
  "Updates come to you": "Las actualizaciones llegan solas",
  "When a new version is ready, a note on the desk offers it, to install after the service.": "Cuando hay una nueva versión lista, un aviso en la mesa te la ofrece para instalarla después del culto.",
