  "Let’s get your church on screen": "Pongamos a tu iglesia en pantalla",
  "About a minute. The preview beside you changes as you answer, so you see your Sunday before it starts.": "Toma un minuto. La vista previa de al lado cambia según respondes, así ves tu domingo antes de que empiece.",
  "Scripture, songs and sermons, ready offline": "Escritura, canciones y sermones, listos sin conexión",
  "Say “next verse” and the desk follows": "Di “next verse” y la mesa te sigue",
  "Nothing reaches the screen until you press LIVE": "Nada llega a la pantalla hasta que presionas EN VIVO",
  "Tell us about your church": "Cuéntanos sobre tu iglesia",
  "The name becomes your logo slide. Tick what you show and the preview shows it.": "El nombre se convierte en tu diapositiva de logo. Marca lo que muestras y la vista previa lo muestra.",
  "What you put on screen": "Lo que pones en pantalla",
  "On Sunday we show": "El domingo mostramos",
  "How it looks on the wall": "Cómo se ve en la pared",
  "Pick the look for verses, songs and your logo slide. Preview and Program change as you pick; the theme library has many more.": "Elige el estilo de los versículos, las canciones y tu diapositiva de logo. Vista previa y Programa cambian según eliges; la biblioteca de temas tiene muchos más.",
  "Colors for your desk": "Colores de tu mesa",
  "This is the desk you work at. The congregation never sees it, so pick what is easy on your eyes in your room.": "Esta es la mesa donde trabajas. La congregación nunca la ve, así que elige lo que sea cómodo para tus ojos en tu sala.",
  "Choose your Bible": "Elige tu Biblia",
  "King James and the World English Bible are installed. Add others now or any time from Settings.": "La King James y la World English Bible ya están instaladas. Agrega otras ahora o cuando quieras desde Ajustes.",
  "{sizeMb} MB": "{sizeMb} MB",
  "Put it on the big screen": "Ponlo en la pantalla grande",
  "Plug in the projector or TV first. The audience window opens there, full screen, and shows only what you send live.": "Primero conecta el proyector o la TV. La ventana del público se abre ahí, en pantalla completa, y solo muestra lo que envías en vivo.",
  "Open the audience window": "Abrir la ventana del público",
  "It is open. Move it to the projector if it opened here.": "Ya está abierta. Muévela al proyector si se abrió aquí.",
  "It opens on the second screen when there is one.": "Se abre en la segunda pantalla si hay una.",
  "Check it from the back row": "Revísalo desde la última fila",
  "A test pattern flashes on the audience screen. Nothing live changes.": "Aparece un patrón de prueba en la pantalla del público. Nada cambia en vivo.",
  "Fit any screen": "Ajustar a cualquier pantalla",
  "Found when the window opens.": "Se detecta al abrir la ventana.",
  "No projector here yet? Continue. The Audience button at the top of the desk does this any time.": "¿Aún no hay proyector? Continúa. El botón Público, arriba en la mesa, hace esto cuando quieras.",
