  "Cameras, OBS or vMix outputs and other computers sending NDI on this network. NDI® is a registered trademark of Vizrt NDI AB.": "Cámaras, salidas de OBS o vMix y otras computadoras que envían NDI en esta red. NDI® es una marca registrada de Vizrt NDI AB.",
