  "{n} watching": "{n} conectados",
  "Any app that takes NDI can show what the audience sees, over the network: vMix, OBS (with its NDI plugin), Wirecast, Resolume, TriCaster, NDI Studio Monitor, a streaming computer. It captures the audience window, which opens if it is closed.": "Cualquier app que reciba NDI puede mostrar lo que ve el público por la red: vMix, OBS (con su plugin NDI), Wirecast, Resolume, TriCaster, NDI Studio Monitor, una computadora de transmisión. Captura la ventana del público, que se abre si está cerrada.",
  "Send sound with the picture": "Enviar el sonido con la imagen",
  "On: videos and music on Program go out over NDI.": "Activado: los videos y la música de Programa salen por NDI.",
  "This NDI or macOS version cannot send sound; the picture still goes out.": "Esta versión de NDI o de macOS no puede enviar sonido; la imagen sí sale.",
  "Videos and music on Program go out with the picture, so the sound desk or the stream gets them over the network too. Needs macOS 13 or later.": "Los videos y la música de Programa salen con la imagen, así la consola de sonido o la transmisión también los reciben por la red. Requiere macOS 13 o posterior.",
  "Sends colour bars, and a beep each second when sound is on, under the same name, so you can add the source in vMix, OBS or any NDI app and check the sound before the service.": "Envía barras de color, y un pitido cada segundo si el sonido está activado, con el mismo nombre, para que agregues la fuente en vMix, OBS o cualquier app NDI y pruebes el sonido antes del culto.",
  "vMix control works in the desktop app.": "El control de vMix funciona en la app de escritorio.",
