  "App": "App",
  "NDI already sends your picture and sound to any NDI app. Connect one here to also press its buttons from the desk: switch its scenes or inputs, start and stop its stream and recording.": "NDI ya envía tu imagen y tu sonido a cualquier app NDI. Conecta una aquí para presionar también sus botones desde la mesa: cambiar sus escenas o entradas, iniciar y detener su transmisión y grabación.",
