  "Report a security problem": "Informar de un problema de seguridad",
  "Learned: “{heard}” means {means}": "Aprendido: «{heard}» significa {means}",
  "Next time it is put right by itself. If that was wrong, remove it.": "La próxima vez se corrige solo. Si era un error, elimínelo.",
  "Misheard words": "Palabras mal entendidas",
  "Accents and names the recognizer gets wrong are put right before verses are found: “efficient 4” becomes Ephesians 4. A book name changes only next to a chapter number, so ordinary speech keeps its words. When you put up a passage the recognizer missed, Church Studio learns the word by itself.": "Los acentos y nombres que el reconocimiento entiende mal se corrigen antes de buscar versículos: «efficient 4» se convierte en Efesios 4. Un nombre de libro solo cambia junto a un número de capítulo, así el habla corriente conserva sus palabras. Cuando muestra un pasaje que el reconocimiento no encontró, Church Studio aprende la palabra solo.",
  "Practice": "Práctica",
  "Read references aloud, as the pastor would, and see what the recognizer writes. Teach it any word it gets wrong.": "Lea referencias en voz alta, como lo haría el pastor, y vea lo que escribe el reconocimiento. Enséñele las palabras que entiende mal.",
  "Say": "Diga",
  "Listening…": "Escuchando…",
