  "main": "principal",
  "Screens with their own job": "Pantallas con su propia tarea",
  "Give each extra monitor a job: a timer for the preacher, only scripture, only lyrics, or the stage view. Lock a screen so nothing changes it during the service; unlocked screens can be switched any time. The desk and the audience screen keep their own monitors.": "Dé una tarea a cada monitor adicional: un temporizador para el predicador, solo Escrituras, solo letras o la vista de escenario. Bloquee una pantalla para que nada la cambie durante el culto; las pantallas desbloqueadas pueden cambiarse en cualquier momento. El escritorio y la pantalla de la congregación conservan sus monitores.",
  "Identify": "Identificar",
  "Screens open on monitors in the desktop app.": "Las pantallas se abren en los monitores en la aplicación de escritorio.",
  "This computer shows {count} monitor(s). Connect another monitor for a screen; the desk and the audience screen use the first two.": "Este ordenador muestra {count} monitor(es). Conecte otro monitor para una pantalla; el escritorio y la pantalla de la congregación usan los dos primeros.",
  "Screen name": "Nombre de la pantalla",
  "Locked: nothing changes this screen": "Bloqueada: nada cambia esta pantalla",
  "Unlocked: its job can be switched": "Desbloqueada: su tarea puede cambiar",
  "Locked": "Bloqueada",
  "Remove screen": "Quitar la pantalla",
  "Monitor": "Monitor",
  "Choose…": "Elegir…",
  "not connected": "no conectado",
  "Job": "Tarea",
  "Locked. Unlock to switch it.": "Bloqueada. Desbloquee para cambiarla.",
  "Add a screen": "Añadir una pantalla",
  "Up to {max} screens. Cameras show on the audience screen only.": "Hasta {max} pantallas. Las cámaras solo se ven en la pantalla de la congregación.",
  "Extra screens are part of Premium.": "Las pantallas adicionales forman parte de Premium.",
  "Add screen": "Añadir pantalla",
  "Extra monitors, each with its own job: timer, scripture, lyrics or stage.": "Monitores adicionales, cada uno con su tarea: temporizador, Escrituras, letras o escenario.",
  "Extra screens with their own job: timer, scripture, lyrics or stage": "Pantallas adicionales con su propia tarea: temporizador, Escrituras, letras o escenario",
  "Screens during this part": "Pantallas durante esta parte",
  "Locked: keeps {job}": "Bloqueada: mantiene {job}",
  "Job for {name} during this part": "Tarea de {name} durante esta parte",
  "Its own job ({job})": "Su propia tarea ({job})",
  "Now showing {job}: the running part asks for it.": "Ahora muestra {job}: la parte en curso lo pide.",
  "Parts of the service can give it another job while they run: choose that in Where it runs.": "Las partes del culto pueden darle otra tarea mientras se desarrollan: elíjala en Dónde se presenta.",
  // 0.2.7
  "Give each extra monitor a job in Settings › Screens: a timer for the preacher, only scripture, only lyrics, or the stage view. Lock a screen so nothing changes it, or let each part of the service switch it.": "Dé una tarea a cada monitor adicional en Ajustes › Pantallas: un temporizador para el predicador, solo Escrituras, solo letras o la vista de escenario. Bloquee una pantalla para que nada la cambie, o deje que cada parte del culto la cambie.",
  "A start that never hangs": "Un inicio que nunca se queda colgado",
  "If Church Studio takes too long to start, it says why and lets you send the details to support.": "Si Church Studio tarda demasiado en iniciar, dice por qué y le permite enviar los detalles al soporte.",
  "Cache cleared: {size} freed.": "Caché vaciada: {size} liberados.",
  "The cache was already small.": "La caché ya era pequeña.",
  "Library compacted: {size} smaller, nothing removed.": "Biblioteca compactada: {size} menos, nada eliminado.",
  "The library was already compact.": "La biblioteca ya estaba compacta.",
  "Speech model removed. Listening uses the system recognizer.": "Modelo de voz eliminado. La escucha usa el reconocimiento del sistema.",
  "Space on this computer": "Espacio en este ordenador",
  "Church Studio uses {size}": "Church Studio usa {size}",
  "Your library is kept small: songs, services and Bibles take little room. Pictures and videos take the most.": "Su biblioteca se mantiene pequeña: cantos, cultos y Biblias ocupan poco. Las imágenes y videos ocupan más.",
  "Songs, services, sermons, settings and Bibles. Compacting rewrites it in less space; nothing is removed.": "Cantos, cultos, sermones, ajustes y Biblias. Compactar la reescribe en menos espacio; no se elimina nada.",
  "Compacting…": "Compactando…",
  "Speech model": "Modelo de voz",
  "For Accurate listening. Remove it to free the space; download it again any time.": "Para la escucha precisa. Elimínelo para liberar espacio; descárguelo de nuevo cuando quiera.",
  "Cache": "Caché",
  "Copies of downloaded files the window keeps to be quicker. Safe to clear any time.": "Copias de archivos descargados que la ventana guarda para ir más rápido. Se puede vaciar en cualquier momento.",
  "Clearing…": "Vaciando…",
  "Clear cache": "Vaciar la caché",
  "{count} unused files removed: {size} freed.": "{count} archivos sin uso eliminados: {size} liberados.",
  "Files added to Media. Find the ones nothing uses: no song, service, sermon, slide, look, theme or setting.": "Archivos añadidos a Medios. Encuentre los que nada usa: ningún canto, culto, sermón, diapositiva, composición, tema o ajuste.",
  "Looking…": "Buscando…",
  "leftover file": "archivo sobrante",
  // 0.2.8
  "Bibles in Ewe, Yorùbá, Igbo, Hausa and Asante Twi": "Biblias en ewe, yoruba, igbo, hausa y twi asante",
  "Five more openly licensed Bibles in Settings › Bible, downloaded only when you choose one, then offline.": "Cinco Biblias más con licencia abierta en Ajustes › Biblia, descargadas solo cuando elige una, y luego sin conexión.",
  "Settings › Storage shows what Church Studio uses, finds pictures and videos nothing uses, and clears the cache or compacts the library.": "Ajustes › Almacenamiento muestra lo que usa Church Studio, encuentra imágenes y videos que nada usa, y vacía la caché o compacta la biblioteca.",
  "Lighter Accurate listening": "Escucha precisa más ligera",
  "The speech model leaves memory a few minutes after you stop listening.": "El modelo de voz sale de la memoria unos minutos después de dejar de escuchar.",
  // 0.2.9
  "Two identical projectors work together": "Dos proyectores idénticos funcionan juntos",
  "Two monitors of the same model are kept apart in Settings, the audience choice and Screens.": "Dos monitores del mismo modelo se distinguen en Ajustes, la elección de la pantalla del público y Pantallas.",
  "A steady Accurate listening download": "Una descarga estable de la escucha precisa",
  "Settings no longer flickers while the speech model downloads, and Cancel stops it at once.": "Ajustes ya no parpadea mientras se descarga el modelo de voz, y Cancelar la detiene al instante.",
  "Storage is easier to find": "El almacenamiento es más fácil de encontrar",
  "Space on this computer is now in Settings › Storage & backup.": "El espacio en esta computadora ahora está en Ajustes › Espacio y respaldo.",
