  "Stage display opened. Drag it to the platform screen. It shows Program and what is on Preview next.": "Pantalla de escenario abierta. Arrástrala a la pantalla de la plataforma. Muestra el Programa y lo que sigue en Vista previa.",
  "The stage display could not open.": "No se pudo abrir la pantalla de escenario.",
