  // Accounts: signing in, the people on a license, and signed-in computers
  "Connect to the internet to change who uses this license.": "Conéctate a internet para cambiar quién usa esta licencia.",
  "Connect to the internet to see where you are signed in.": "Conéctate a internet para ver dónde has iniciado sesión.",
  "Connect to the internet to sign a computer out.": "Conéctate a internet para cerrar la sesión de un ordenador.",
  "Everything is unlocked, on any computer you sign in on.": "Todo está desbloqueado, en cualquier ordenador donde inicies sesión.",
  "Sign in in your browser to add this key. It is added as soon as you are signed in.": "Inicia sesión en tu navegador para añadir esta clave. Se añade en cuanto inicies sesión.",
  "Sign in in your browser to start your free trial. It stays with you on any computer.": "Inicia sesión en tu navegador para empezar tu prueba gratuita. Te acompaña en cualquier ordenador.",
  "Google, Microsoft, Apple or an email link. Your trial and any plan follow you to every computer. You can also sign in later.": "Google, Microsoft, Apple o un enlace por correo. Tu prueba y tu plan te acompañan en cada ordenador. También puedes iniciar sesión más tarde.",
  "Sign in there, then type this code.": "Inicia sesión allí y escribe este código.",
  "Sign in to start your free trial": "Inicia sesión para empezar tu prueba gratuita",
  "Type {code} on the sign-in page": "Escribe {code} en la página de inicio de sesión",
  "A computer nobody opens for six months signs itself out.": "Un ordenador que nadie abre durante seis meses cierra la sesión solo.",
  "Add person": "Añadir persona",
  "Add someone by the email they sign in with. Their computers then use this license, up to its seats.": "Añade a alguien con el correo con el que inicia sesión. Sus ordenadores usarán esta licencia, hasta sus puestos.",
  "Email to add": "Correo para añadir",
  "Needed for the free trial and to add a license key. Your plan then follows you, so another computer only needs you to sign in. Google, Microsoft, Apple or an email link, in your browser.": "Necesario para la prueba gratuita y para añadir una clave de licencia. Luego tu plan te acompaña: en otro ordenador solo tienes que iniciar sesión. Google, Microsoft, Apple o un enlace por correo, en tu navegador.",
  "Open the page on any phone or computer, sign in, then type:": "Abre la página en cualquier teléfono u ordenador, inicia sesión y escribe:",
  "People on your {plan} license": "Personas en tu licencia {plan}",
  "Show computers": "Mostrar ordenadores",
  "Sign in on another device": "Iniciar sesión en otro dispositivo",
  "Sign in there and choose Continue. Church Studio carries on by itself.": "Inicia sesión allí y elige Continuar. Church Studio sigue solo.",
  "Sign out everywhere else": "Cerrar sesión en todos los demás",
  "Sign-in code {code}": "Código de inicio de sesión {code}",
  "Type this code on the sign-in page": "Escribe este código en la página de inicio de sesión",
  "Use a code instead": "Usar un código",
  "Where you are signed in": "Dónde has iniciado sesión",
  // What's new in 0.3.0
  "Sign in once, in your browser": "Inicia sesión una vez, en tu navegador",
  "Sign in comes back to Church Studio by itself, with no number to tap. From a phone or another computer, type the short code instead.": "El inicio de sesión vuelve solo a Church Studio, sin número que tocar. Desde un teléfono u otro ordenador, escribe el código corto.",
  "Your plan goes with you": "Tu plan te acompaña",
  "The free trial and license keys now belong to your account. Add your team by email in Settings › Account, and see every computer you are signed in on.": "La prueba gratuita y las claves de licencia ahora pertenecen a tu cuenta. Añade a tu equipo por correo en Ajustes › Cuenta y ve cada ordenador donde has iniciado sesión.",
  "Steadier on Sunday": "Más estable el domingo",
  "Installing a Bible, importing a video or starting to listen no longer freezes the desk or the projector, and quick clicks through verses always land on the right one.": "Instalar una Biblia, importar un vídeo o empezar a escuchar ya no congela el escritorio ni el proyector, y los clics rápidos por los versículos siempre llegan al correcto.",
  "Every screen shape": "Todas las formas de pantalla",
  "Looks with gaps or frames, theme previews and slide pages follow your screen's real shape, 4:3 and portrait included.": "Los diseños con espacios o marcos, las vistas previas de temas y las páginas de diapositivas siguen la forma real de tu pantalla, 4:3 y vertical incluidos.",
  "Clearer in French and Spanish": "Más claro en francés y español",
